import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Develop the frontend","description":"Understand the Ershu frontend boundary, structure, request flow, and complete validation path for a new page.","frontmatter":{"page_id":"development-frontend","description":"Understand the Ershu frontend boundary, structure, request flow, and complete validation path for a new page."},"headers":[],"relativePath":"en/development/frontend.md","filePath":"en/development/frontend.md","lastUpdated":1786290726000}'),i={name:"en/development/frontend.md"};function o(r,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="develop-the-frontend" tabindex="-1">Develop the frontend <a class="header-anchor" href="#develop-the-frontend" aria-label="Permalink to &quot;Develop the frontend&quot;">​</a></h1><p>The Ershu frontend is an independent repository. It owns browser UI, browser state, and HTTP requests. It does not import source from Core, API, Worker, or MCP. Before changing a page, confirm the contract through a running Ershu instance and published interfaces. A backend directory that happens to exist beside your checkout must not become an implicit dependency.</p><h2 id="technology-and-runtime-boundary" tabindex="-1">Technology and runtime boundary <a class="header-anchor" href="#technology-and-runtime-boundary" aria-label="Permalink to &quot;Technology and runtime boundary&quot;">​</a></h2><p>The current frontend uses:</p><ul><li>Node.js 24;</li><li>Vite 7;</li><li>React 19;</li><li>React Router with hash routing;</li><li>TypeScript;</li><li>Tailwind CSS and Radix components; and</li><li><code>markdown-it</code>, Mermaid, and graph components.</li></ul><p>Hash routing allows static files to host runtime pages. Chinese routes look like <code>#/zh/projects</code>, while English routes look like <code>#/en/projects</code>.</p><p>The frontend knows only public HTTP contracts. Queue processing, authorization decisions, document generation, and search behavior remain backend responsibilities. The UI must not turn a local guess into a server fact.</p><h2 id="directory-responsibilities" tabindex="-1">Directory responsibilities <a class="header-anchor" href="#directory-responsibilities" aria-label="Permalink to &quot;Directory responsibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>src/app.tsx</code></td><td>Routes, authentication guards, project layout, and global providers</td></tr><tr><td><code>src/pages/</code></td><td>Thin entry points corresponding to routes</td></tr><tr><td><code>src/features/</code></td><td>Page controllers, views, and independently testable state logic</td></tr><tr><td><code>lib/api/</code></td><td>Request methods and types, cookie handling, and CSRF behavior</td></tr><tr><td><code>lib/api-client.ts</code></td><td>Aggregation of the API client modules</td></tr><tr><td><code>lib/auth-context.tsx</code></td><td>Authentication state, session restoration, refresh, and sign-out</td></tr><tr><td><code>lib/i18n.ts</code></td><td>Chinese and English message lookup and locale path parsing</td></tr><tr><td><code>messages/zh.json</code>, <code>messages/en.json</code></td><td>UI text for both languages</td></tr><tr><td><code>lib/theme-provider.tsx</code></td><td>Light, dark, and system theme selection</td></tr><tr><td><code>components/</code></td><td>Shared layout and UI components</td></tr><tr><td><code>hooks/</code></td><td>Event-stream and shared interaction hooks</td></tr></tbody></table><p>Put requests in <code>lib/api/</code>, reusable state under <code>src/features/</code>, and keep <code>src/pages/</code> focused on composition. A page entry should not own requests, state, rendering, and copy at the same time.</p><h2 id="start-the-frontend-locally" tabindex="-1">Start the frontend locally <a class="header-anchor" href="#start-the-frontend-locally" aria-label="Permalink to &quot;Start the frontend locally&quot;">​</a></h2><p>In the independent frontend repository, run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The development server listens on <code>http://localhost:3000</code> by default. A successful start leaves the process running, and the browser enters initial administrator setup, sign-in, or the project list instead of showing a static blank page.</p><p>The frontend has four build-time settings:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td><code>/api/v1</code></td><td>Base path for browser API requests</td></tr><tr><td><code>VITE_CSRF_COOKIE_NAME</code></td><td><code>ershu_csrf</code></td><td>Name of the CSRF cookie</td></tr><tr><td><code>VITE_DEV_API_PROXY</code></td><td><code>http://localhost:8000</code></td><td>API proxy target in development</td></tr><tr><td><code>VITE_DEV_MCP_PROXY</code></td><td><code>http://127.0.0.1:8001</code></td><td>MCP proxy target in development</td></tr></tbody></table><p>Restart the development server after changing a proxy target. Model names, model API keys, and model-channel endpoints are not build settings; administrators configure them in the web interface.</p><h2 id="add-or-change-a-page" tabindex="-1">Add or change a page <a class="header-anchor" href="#add-or-change-a-page" aria-label="Permalink to &quot;Add or change a page&quot;">​</a></h2><h3 id="_1-confirm-the-interface-contract" tabindex="-1">1. Confirm the interface contract <a class="header-anchor" href="#_1-confirm-the-interface-contract" aria-label="Permalink to &quot;1. Confirm the interface contract&quot;">​</a></h3><p>Use the running Ershu MCP, interface documentation, and actual responses to confirm:</p><ul><li>path and request method;</li><li>request and response fields;</li><li>access requirements;</li><li>failure states; and</li><li>whether a long task uses a snapshot, event stream, or final result.</li></ul><p>You should be able to trace every displayed field to a public response rather than a backend-internal object.</p><h3 id="_2-extend-the-api-client" tabindex="-1">2. Extend the API client <a class="header-anchor" href="#_2-extend-the-api-client" aria-label="Permalink to &quot;2. Extend the API client&quot;">​</a></h3><p>Add the request and its types to the appropriate module under <code>lib/api/</code>, then export them through the client entry point. Keep using the shared request layer so cookie, CSRF, error parsing, and session-refresh behavior remain consistent.</p><p>Requests that submit a password, token, SSH key, or model API key must also use the existing secure-transport check. Localhost is permitted for development; another hostname requires HTTPS.</p><p>The completed method should be importable by feature code, with no page assembling a second API base URL by hand.</p><h3 id="_3-put-state-and-views-in-a-feature-directory" tabindex="-1">3. Put state and views in a feature directory <a class="header-anchor" href="#_3-put-state-and-views-in-a-feature-directory" aria-label="Permalink to &quot;3. Put state and views in a feature directory&quot;">​</a></h3><p>Under <code>src/features/&lt;feature&gt;/</code>, separate:</p><ul><li>the controller that loads and submits data;</li><li>the view that presents it;</li><li>browser-independent state transitions and helpers; and</li><li>tests for that pure logic.</li></ul><p>This makes state transitions, permission-dependent visibility, and failure handling testable without duplicating a page component.</p><h3 id="_4-connect-the-page-and-route" tabindex="-1">4. Connect the page and route <a class="header-anchor" href="#_4-connect-the-page-and-route" aria-label="Permalink to &quot;4. Connect the page and route&quot;">​</a></h3><p>Add a thin entry under <code>src/pages/</code>, then lazy-load it from <code>src/app.tsx</code>. Project pages belong below <code>/:locale/projects/:projectId</code>; global administration pages stay within the existing workspace structure.</p><p>Both the Chinese and English URLs should open the page, and an unauthenticated user should still return to the sign-in page in the corresponding locale.</p><h3 id="_5-keep-chinese-and-english-copy-aligned" tabindex="-1">5. Keep Chinese and English copy aligned <a class="header-anchor" href="#_5-keep-chinese-and-english-copy-aligned" aria-label="Permalink to &quot;5. Keep Chinese and English copy aligned&quot;">​</a></h3><p>Add the same message-key structure to <code>messages/zh.json</code> and <code>messages/en.json</code>. Do not hard-code a notice for only one language, and do not leave fallback or degradation messages in English on the Chinese page.</p><p>After changing language, the current page and object identifier should remain the same; only the locale segment and UI text should change.</p><h3 id="_6-preserve-long-running-task-semantics" tabindex="-1">6. Preserve long-running task semantics <a class="header-anchor" href="#_6-preserve-long-running-task-semantics" aria-label="Permalink to &quot;6. Preserve long-running task semantics&quot;">​</a></h3><p>Run detail must distinguish active and terminal states:</p><ul><li>an active run loads a snapshot and then connects after its cursor;</li><li><code>completed</code> and <code>completed_with_warnings</code> load the final result directly;</li><li><code>failed</code> and <code>cancelled</code> do not keep an event stream open; and</li><li>refreshing the page must not create another run.</li></ul><p>Chat on Docs is currently project-scoped. Opening a document does not make a request document- or section-scoped.</p><h2 id="validate-the-change" tabindex="-1">Validate the change <a class="header-anchor" href="#validate-the-change" aria-label="Permalink to &quot;Validate the change&quot;">​</a></h2><p>Run these commands in order before submitting the change:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Use these acceptance conditions:</p><ul><li><code>npm test</code> exits with code <code>0</code>;</li><li><code>npm run lint</code> passes both code and TypeScript checks;</li><li><code>npm run format:check</code> lists no file that needs reformatting; and</li><li><code>npm run build</code> exits with code <code>0</code> and creates <code>dist/</code>.</li></ul><p>The current automated suite mainly covers state logic, request contracts, and event processing. It is not a complete browser end-to-end suite. Also check manually:</p><ul><li>Chinese and English routes;</li><li>light, dark, and system themes;</li><li>a narrow viewport around 375 pixels and common desktop widths;</li><li>keyboard operation and focus;</li><li>expired authentication, request failures, and empty data;</li><li>refreshing an active run and loading a completed run.</li></ul><p>If a check fails, use <a href="./troubleshooting">development troubleshooting</a> instead of hiding the problem by deleting a test or weakening an interface type.</p>`,48)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
